struct timex tx = {0};

// To read only, modes=0
tx.modes = 0;

// To set frequency and status
tx.modes = ADJ_FREQUENCY | ADJ_STATUS;
tx.freq = 1500;       // Parts per billion
tx.status = STA_PLL;  // Enable PLL

// Apply adjustments and retrieve current state
int result = adjtimex(&tx);

// tx now contains current kernel clock values
// Result >= 0 for success
long current_offset = tx.offset;
